//! Cargo-driven `d3drm.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x763e0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff4e000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff4e000000u64)),
        o => panic!("d3drm-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "import:ddraw", "import:d3dxof", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["engine:wine", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "import:ddraw", "import:d3dxof", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["engine:wine", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "import:ddraw", "import:d3dxof", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/d3drm",
        "dll/directx/wine/d3drm",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("d3drm_shims", &["dll/directx/wine/d3drm/d3drm.c", "dll/directx/wine/d3drm/d3drm_main.c", "dll/directx/wine/d3drm/device.c", "dll/directx/wine/d3drm/face.c", "dll/directx/wine/d3drm/frame.c", "dll/directx/wine/d3drm/light.c", "dll/directx/wine/d3drm/material.c", "dll/directx/wine/d3drm/math.c", "dll/directx/wine/d3drm/meshbuilder.c", "dll/directx/wine/d3drm/texture.c", "dll/directx/wine/d3drm/viewport.c"])
        .rc("dll/directx/wine/d3drm/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/d3drm/d3drm.spec", "d3drm.dll")
        .spec_stubs()
        .import_lib("dll/directx/wine/ddraw/ddraw.spec", "ddraw.dll", "ddraw")
        .import_lib("dll/directx/wine/d3dxof/d3dxof.spec", "d3dxof.dll", "d3dxof")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
